        static HarborDeckContact[] MeasureActualQuayArtSupport(DragonKingdomWorld world,Transform art,Transform quay,float surface,bool required=true)
        {
            var own=new HashSet<Collider>(art.GetComponentsInChildren<Collider>(true));var b=BoundsOf(art);var result=new List<HarborDeckContact>();
