            {
                var p=new Vector3(x,surface+.5f,z);var hits=Physics.RaycastAll(p,Vector3.down,1,~0,QueryTriggerInteraction.Ignore).Where(h=>!own.Contains(h.collider)&&h.collider.transform.IsChildOf(quay)&&h.normal.y>.5f).OrderByDescending(h=>h.point.y).ToArray();var hit=hits.FirstOrDefault();var record=new HarborDeckContact{requested=p,actual=hit.point,collider=hit.collider==null?null:PathOf(hit.collider.transform,world.transform),passed=hit.collider!=null&&Mathf.Abs(hit.point.y-surface)<=.04f};result.Add(record);
            }
            if(required&&result.Any(r=>!r.passed))throw new InvalidOperationException("Actual harbor decoration has an unsupported native timber-deck foot sample; no flooded terrain relabeling.");return result.ToArray();
        }
