        public static void ValidateSavedHarborForecourt(DragonKingdomWorld world,HarborForecourt proof)
        {
            if(proof==null||!proof.passed||proof.modules!=40||proof.piers+proof.sourceBearingStations!=12||proof.sourceBearingContacts.Length!=proof.sourceBearingStations||proof.supportedDecorations!=22||proof.decorationFootSamples!=198||proof.departureQueries!=53||proof.minimumDepartureLateralClearance<10||!proof.departureCorridorClear||!proof.originalFerryPoseExact||proof.parts.Length!=proof.modules+proof.piers||proof.decorations.Length!=22||proof.decorationPlacements.Length!=22||proof.decorationPlacements.Any(p=>!p.acceptedNativeLayout)||proof.deckContacts.Any(c=>!c.passed))throw new InvalidOperationException("Saved actual harbor support proof is incomplete.");
            var root=world.Region("harbor").root.Cast<Transform>().Single(t=>t.name==HarborQuaysideName);if(root.childCount!=proof.parts.Length)throw new InvalidOperationException("Saved actual quay source count differs.");var hashes=new Dictionary<string,string>();
            foreach(var part in proof.parts.Concat(proof.decorations))
            {
                var owner=proof.parts.Contains(part)?root:world.Region("harbor").root;var t=owner.Cast<Transform>().Single(v=>v.name==part.name);if(t.position!=part.position||Quaternion.Angle(t.rotation,part.rotation)>.0001f||t.localScale!=part.scale||AssetDatabase.AssetPathToGUID(part.source)!=part.guid||AssetSha(part.source)!=part.sourceSha256||AssetSha(part.source+".meta")!=part.sourceMetaSha256||JsonUtility.ToJson(new RidgeGeometryContainer{bindings=RidgeGeometryBindings(t,hashes)})!=JsonUtility.ToJson(new RidgeGeometryContainer{bindings=part.geometry}))throw new InvalidOperationException("Saved actual quay source/pose/native-collision geometry differs: "+part.name);
            }
            foreach(var contact in proof.pierContacts)if(Mathf.Abs(DragonKingdomTerrainShoulderAuthoring.TerrainHeight(world,contact.position)-contact.nativeBed)>.0001f||!contact.baseContact||!contact.deckContact)throw new InvalidOperationException("Saved actual quay bed support differs.");
            foreach(var contact in proof.sourceBearingContacts)if(!contact.passed||contact.sourceUnderside>contact.nativeBed+.02f||Mathf.Abs(DragonKingdomTerrainShoulderAuthoring.TerrainHeight(world,contact.position)-contact.nativeBed)>.0001f)throw new InvalidOperationException("Saved original dock-to-ground bearing contact differs.");
            if(Pose(world.extractionSites.Single(s=>s.vessel!=null).vessel.transform)!=proof.originalFerryPose||!FinishBoundsClearOfRoads(world,proof.bounds))throw new InvalidOperationException("Saved original ferry or quay road separation changed.");
        }
