            var root=new GameObject(HarborCargoName).transform;root.SetParent(harbor.root,false);var contacts=new List<HarborDeckContact>();float highest=float.NegativeInfinity;
            foreach(float z in new[]{-740f,-730f})foreach(float x in new[]{802.7f,807.3f})
            {
                var start=new Vector3(x,12,z);var hits=new List<RaycastHit>();foreach(var collider in hullColliders)if(collider.Raycast(new Ray(start,Vector3.down),out var hit,32)&&hit.normal.y>.35f)hits.Add(hit);if(hits.Count==0)throw new InvalidOperationException("No actual upward source-hull surface for merchant freight support.");var top=hits.OrderByDescending(h=>h.point.y).First();highest=Mathf.Max(highest,top.point.y);contacts.Add(new HarborDeckContact{requested=start,actual=top.point,collider=PathOf(top.collider.transform,world.transform),passed=true});
            }
