            for(int i=0;i<4;i++)
            {string source=DragonKingdomWorldAuthoring.Village+"props/"+(i%2==0?"P_PROP_crate_01":"P_PROP_sack_01")+".prefab";var t=DragonKingdomWorldAuthoring.PlaceOwnedArtForReview(root,source,new Vector3(i%2==0?803.5f:806.5f,proof.deckSurface,-739+i/2*8),i*90,1.25f,true);t.name="Owned actual trader freight "+i;ConfigureFinishMaterials(t,folder);AlignBase(t,new Vector3(i%2==0?803.5f:806.5f,proof.deckSurface,-739+i/2*8));parts.Add(DescribeHarborPart(t,source));finish.sources.Add(source);proof.freight++;}
            Physics.SyncTransforms();proof.parts=parts.ToArray();proof.bounds=BoundsOf(root);proof.protectedHullExact=originalGeometry==JsonUtility.ToJson(new RidgeGeometryContainer{bindings=RidgeGeometryBindings(ship,new Dictionary<string,string>())});var ferry=world.extractionSites.Single(s=>s.vessel!=null).vessel;proof.departureClear=proof.bounds.min.x>=ferry.transform.position.x+22&&FinishBoundsClearOfRoads(world,proof.bounds);proof.passed=proof.deckPlanks==6&&proof.hullSupports==4&&proof.canopies==1&&proof.freight==4&&proof.protectedHullExact&&proof.departureClear&&proof.minimumDeckFreeboard>=.44f&&proof.bounds.min.x>=800&&proof.bounds.max.x<=810&&proof.bounds.min.z>=-742&&proof.bounds.max.z<=-728&&proof.bounds.min.y>=finish.mooredShip.hullKeel;
            if(!proof.passed)throw new InvalidOperationException("Source-supported trader freight rejects actual hull/ferry/bounded composition: "+JsonUtility.ToJson(proof));finish.sources.Add(beam);records.Add(new Placement{region="harbor",name=root.name,source=beam,operation="Separate source-supported freight deck/canvas/cargo on actual trader hull; protected original hull subtree unchanged",after=root.position,bounds=proof.bounds});return proof;
