        public static void ValidateSavedTraderCargo(DragonKingdomWorld world,HarborCargo proof)
        {
            if(proof==null||!proof.passed||!proof.protectedHullExact||!proof.departureClear||proof.minimumDeckFreeboard<.44f||proof.deckPlanks!=6||proof.hullSupports!=4||proof.freight!=4||proof.canopies!=1||proof.parts.Length!=15||proof.hullContacts.Length!=4)throw new InvalidOperationException("Saved trader freight proof incomplete.");var harbor=world.Region("harbor");var ship=harbor.root.Cast<Transform>().Single(t=>t.name=="Actual owned side-moored trader ship");if(proof.protectedHullGeometry!=JsonUtility.ToJson(new RidgeGeometryContainer{bindings=RidgeGeometryBindings(ship,new Dictionary<string,string>())}))throw new InvalidOperationException("Saved protected original trader hull changed.");var root=harbor.root.Cast<Transform>().Single(t=>t.name==HarborCargoName);if(root.childCount!=15)throw new InvalidOperationException("Saved actual trader freight source count changed.");foreach(var part in proof.parts){var child=root.Cast<Transform>().Single(t=>t.name==part.name);if(child.position!=part.position||Quaternion.Angle(child.rotation,part.rotation)>.0001f||child.localScale!=part.scale||AssetSha(part.source)!=part.sourceSha256||AssetSha(part.source+".meta")!=part.sourceMetaSha256||AssetDatabase.AssetPathToGUID(part.source)!=part.guid||JsonUtility.ToJson(new RidgeGeometryContainer{bindings=RidgeGeometryBindings(child,new Dictionary<string,string>())})!=JsonUtility.ToJson(new RidgeGeometryContainer{bindings=part.geometry}))throw new InvalidOperationException("Saved actual freight source geometry/pose changed: "+part.name);}
        }
    }
}
